(async()=>{
 const wait=()=>new Promise(r=>setTimeout(r,180)),check=(v,m)=>{if(!v)throw Error(m)},state=()=>JSON.parse(localStorage.getItem('collaboration-prototype-v1'));
 const go=async p=>{location.hash=p;await wait()},click=async(t,scope=document)=>{const e=[...scope.querySelectorAll('button,a')].find(e=>(e.textContent.trim()===t||e.getAttribute('aria-label')===t)&&!e.disabled);check(e,'Missing '+t);e.click();await wait()};
 const fill=async(label,value)=>{const e=document.querySelector(`[aria-label="${label}"]`)||document.querySelector(`[name="${label}"]`);check(e,'Missing '+label);Object.getOwnPropertyDescriptor(e.tagName==='TEXTAREA'?HTMLTextAreaElement.prototype:HTMLInputElement.prototype,'value').set.call(e,value);e.dispatchEvent(new Event('input',{bubbles:true}));await wait()};
 const checks=[];
 await go('/p/launch/flow');check(document.querySelector('main h1')?.textContent==='工作流','Default URL did not open list');check(!document.querySelector('.react-flow'),'List is singleton canvas');
 await click('新建工作流');await fill('工作流名称','运营交付流程');await fill('工作流说明','从方案确认到材料验收');await fill('操作理由','项目新增独立运营流程');await click('保存',document.querySelector('dialog[open]'));
 const first=state().projectWorkflows.launch.find(w=>w.name==='运营交付流程');check(first?.flow.flowVersion===0&&first.flow.flowDraft.nodes.length>0,'Creation invented publication or lost draft');check(new URLSearchParams(location.hash.split('?')[1]).get('workflow_id')===first.id,'Created workflow identity absent URL');check(document.querySelector('.react-flow__node'),'New draft opens empty canvas');check(document.querySelector('main').textContent.includes('草案 · 待校验'),'New draft not editable');checks.push('list/create/identity/editable unpublished draft');
 await go('/p/launch/flow');await fill('搜索当前授权列表','运营');check(JSON.parse(new URLSearchParams(location.hash.split('?')[1]).get('state.workflow-list')).query==='运营','Search not in URL');check(document.querySelector('main').textContent.includes('运营交付流程')&&!document.querySelector('main').textContent.includes('保留原项目工作流'),'Search ineffective');await fill('搜索当前授权列表','');
 const section=[...document.querySelectorAll('main tbody tr')].find(e=>e.textContent.includes('运营交付流程'));check(section,'Named workflow row absent');await click('更多操作',section);await click('归档工作流',document.querySelector('dialog[open]'));await fill('操作理由','暂停此定义用于新工作');await click('确认归档',document.querySelector('dialog[open]'));check(state().projectWorkflows.launch.find(w=>w.id===first.id).archivedAt,'Archive not persisted');
 await click('已归档');check(JSON.parse(new URLSearchParams(location.hash.split('?')[1]).get('state.workflow-list')).filter==='archived','Archive filter not URL');check(document.querySelector('main').textContent.includes('运营交付流程'),'Archived record lost');await go(`/p/launch/flow?workflow_id=${first.id}`);check(document.querySelector('main').textContent.includes('查看定义')&&document.querySelector('.react-flow__node'),'Archived draft lost readonly definition');check([...document.querySelectorAll('main button')].find(e=>e.textContent.trim()==='编辑新草案')?.disabled,'Archived definition editable');checks.push('search/status URL/archive readonly');
 await go('/p/launch/flow?workflow_id=missing');check(document.querySelector('main').textContent.includes('工作流不存在')&&!document.querySelector('.react-flow'),'Unknown identity silently defaulted/crashed');
 await go('/p/launch/flow?workflow_id=default&view=runs');check(document.querySelector('main h1').textContent.includes('关联工作'),'Runs URL shows editor');check(document.querySelector('main').textContent.includes('W-104'),'Existing work not linked to default');
 await go(`/p/launch/flow?workflow_id=${first.id}&view=runs`);check(document.querySelector('main').textContent.includes('暂无关联工作')&&!document.querySelector('main').textContent.includes('W-104'),'Named flow inherited default runs');checks.push('unknown identity rejected; associated works isolated');
 await go('/chat?channel_id=launch');const base=location.hash;if(![...document.querySelectorAll('button')].some(e=>e.textContent.trim()==='查看工作流'))await click('切换会话上下文');await click('查看工作流');check(location.hash.startsWith('#/chat?')&&document.querySelector('dialog[open]'),'Chat workflow jumped route');await click('查看 / 编辑定义',document.querySelector('dialog[open]'));check(document.querySelector('dialog[open] .react-flow')&&location.hash.startsWith('#/chat?'),'Popup definition jumped');await click('返回工作流列表',document.querySelector('dialog[open]'));await click('更多操作',document.querySelector('dialog[open]'));await click('关联工作',document.querySelector('dialog[open]'));check(document.querySelector('dialog[open]').textContent.includes('关联工作')&&!document.querySelector('dialog[open] .react-flow'),'Popup runs falsely shows editor');check(location.hash.startsWith('#/chat?')&&document.querySelector('.messages'),'Popup lost chat');await click('返回工作流列表',document.querySelector('dialog[open]'));check(document.querySelectorAll('dialog[open]').length===1&&!document.querySelector('dialog[open]').textContent.includes('工作流操作'),'Returning from related work reopened stale workflow row operations');checks.push('chat popup list/definition/runs preserves conversation');
 const popupQuery=new URLSearchParams({channel_id:'launch','state.chat-flow-preview':JSON.stringify({tenantId:state().activeTenant,channelId:'launch',projectId:'launch',workflowId:'default',version:'3',flowState:{}})});
 await go('/chat?'+popupQuery);let popup=document.querySelector('dialog[open]');check(popup?.textContent.includes('固定版本 v3'),'Historical popup deep link did not restore fixed v3');await click('查看最新定义',popup);popup=document.querySelector('dialog[open]');check(popup.textContent.includes('已发布 v3')&&!popup.textContent.includes('固定版本只读'),'Latest definition remains stuck at historical fallback');
 const popupState=JSON.parse(new URLSearchParams(location.hash.split('?')[1]).get('state.chat-flow-preview'));check(popupState.flowState.version===null,'Latest popup selection lost explicit null in precise URL');const openLink=[...popup.querySelectorAll('a')].find(e=>e.textContent==='在新标签页打开工作流');check(openLink&&!new URLSearchParams(openLink.getAttribute('href').split('?')[1]).has('version'),'New tab link still points to historical version');checks.push('historical popup to latest retains null and exact new-tab destination');

 const historyQuery=new URLSearchParams({channel_id:'launch','state.chat-flow-preview':JSON.stringify({tenantId:state().activeTenant,channelId:'launch',projectId:'launch',workflowId:'default',version:'3',flowState:{version:3}})});
 await go('/chat?'+historyQuery);popup=document.querySelector('dialog[open]');await click('返回工作流列表',popup);popup=document.querySelector('dialog[open]');
 const listLink=[...popup.querySelectorAll('a')].find(e=>e.textContent==='在新标签页打开工作流');const listParams=new URLSearchParams(listLink.getAttribute('href').split('?')[1]);
 check(!listParams.has('workflow_id')&&!listParams.has('version'),'Returning from historical definition contaminates list destination');
 check(!document.querySelector('dialog[open] .react-flow'),'Returning from historical definition did not open list');checks.push('historical popup return clears version in new-tab list link');
 check(document.documentElement.scrollWidth<=innerWidth,'Viewport overflow');return {pass:true,width:innerWidth,checks};
})();
